        assert(td || !nested);

        if (is_buf)
                f = NULL;
        else {
                if (!strcmp(file, "-")) {
                        f = stdin;
                        stdin_occupied = true;
                } else
                        f = fopen(file, "r");

                if (!f) {
                        int __err = errno;

                        log_err("fio: unable to open '%s' job file\n", file);
